pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact match between post_residual and next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();

        // Perfect chaining: item fits exactly, next item fills the remainder.
        if diff < 0.5 {
            score -= 60.0 + 30.0 * (1.0 - progress);
        } else if post_residual as f64 > nxt {
            // Next item can still fit in the leftover: partial reward, decaying with gap.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            score += 10.0 + 0.5 * diff;
        }
    } else {
        // Last item: minimize final dead space aggressively.
        score += 20.0;
    }

    // --- Mean-residual coupling: prefer bins whose post-residual deviates usefully ---
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Ending below the mean residual = tight packing, reward it.
        score -= 0.6 * (-dev);
    } else {
        // Ending above the mean residual = loose packing, mild penalty.
        score += 0.3 * dev;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling: only open a new bin when nothing fits well ---
    if bin_residual == bin_capacity {
        // Base preference for reusing an existing bin.
        score += 35.0;
        // But if existing bins are all poor fits (large mean residual, tight fits rare),
        // opening a fresh bin becomes attractive for future flexibility.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 70.0; // fresh bin chains perfectly with next item
        }
        if mean_residual < 15.0 && fitting_bins_count > 0 {
            // Existing bins are nearly full already; new bin is fine.
            score -= 10.0;
        }
    }

    // --- Squared dead-space penalty for very small leftovers (unusable fragments) ---
    if post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill: big reward.
        score -= 50.0;
    }

    // Slight pressure to consolidate early in the stream.
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Penalize small dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 500.0;
        } else {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        }
    }
    // Penalize if next item would NOT fit here (this bin becomes dead for it).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Time horizon: early in stream, be conservative with open bins;
    // late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> discourage new bin, encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: must beat existing bins only when
        // existing fits are poor or there are few bins.
        score += 30.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // reserve space for a large upcoming item
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    } else {
        // Existing bin: reward being below mean residual (more roomy bin used).
        score += 5.0 * ((mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64);
        // Consolidation pressure when too many bins open.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins with residual close to item (harmonic-ish).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Early on, tight fits matter less (bins can still be filled); later,
    // small residuals become dead weight, so weight grows with t.
    let mut score = pr * (1.0 + 2.0 * t * norm_pr) + norm_pr * norm_pr * cap * (0.5 + t);

    // Smooth progress-based cubic coupling: reward tight fits more as stream ends.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * (20.0 + 60.0 * t);

    // Lookahead: if next item fits into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_after = nxt / pr.max(1.0);
            score -= 10.0 * fill_after * (1.0 + t);
        } else {
            // residual that cannot host the next item is more likely dead space
            score += 5.0 * (1.0 - pr / nxt) * (0.5 + t);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 40.0 * t;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item wastes relatively less
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is tighter than average -> bonus; far above -> mild penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0 - dev * 10.0 * (0.5 + t);

    // New-bin candidate: empty bin has no wasted space yet; make it attractive
    // only when the item leaves a very awkward residual or late in the stream.
    if bin_residual == bin_capacity {
        let awkward = (norm_pr - 0.5).abs(); // post_residual far from half-capacity
        let openness = 1.0 / (1.0 + (open_bins_count as f64).ln().max(0.0));
        score = 30.0 + 90.0 * (1.0 - awkward) * openness - 40.0 * t * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify leftover space ---
    // Residual classes by integer division into harmonic buckets of capacity/10
    let bucket = (post_residual * 10) / bin_capacity; // 0..=10
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic penalty: buckets that are "dead space" classes (1..9) get a
    // non-linear penalty; exact zero (perfect fit) heavily rewarded,
    // full-ish residuals (bucket 10, i.e., item tiny) mildly penalized.
    match bucket {
        0 => { score -= 40.0; }                       // perfect fit
        1 => { score += 18.0 + 6.0 * progress; }      // nearly dead space
        2 => { score += 26.0; }
        3 => { score += 20.0; }
        4 => { score += 12.0; }
        5 => { score += 6.0; }
        6 => { score += 2.0; }
        7..=9 => { score += 1.0; }                    // still reusable classes
        _ => { score += 15.0; }                       // bucket 10: huge leftover, wasteful placement
    }

    // --- Modulo coupling: post_residual vs next_item_size ---
    // If the lookahead item can fit exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic residue: how close next item is to filling leftover
            let gap = post_residual - next_item_size;
            let gap_bucket = (gap * 10) / bin_capacity;
            score -= 12.0 - 2.0 * gap_bucket as f64;
            // modulo classes: gap divisible by common item granularities (5,10)
            if gap % 10 == 0 { score -= 4.0; }
            else if gap % 5 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // --- Last-chance logic: only one bin fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0; // must use it or lose it
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost, reduced late in stream or when few bins fit
        let mut new_bin_score = 55.0;
        if fitting_bins_count == 0 { new_bin_score -= 60.0; } // no alternative
        if next_item_size > 0 && next_item_size > mean_residual.max(0.0) { new_bin_score -= 8.0; }
        new_bin_score += 10.0 * (1.0 - progress); // prefer reusing bins early
        score = new_bin_score;
    }

    // --- Mean residual coupling: discourage scattering across many open bins ---
    if bin_residual != bin_capacity {
        if (post_residual as f64) < mean_residual {
            score -= 3.0; // tighter than average: good consolidation
        } else {
            score += 2.0;
        }
        // pressure from number of open bins
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
