pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Lookahead: reward if the next item fits into the post residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste;
        } else if next_item_size > 0 {
            // Next item won't fit here: penalize dead space relative to next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }

        // Penalize small unusable residuals (dead space), worse mid-stream.
        if post_residual < 10 {
            score += 25.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Prefer bins below mean residual (use emptier bins for big items,
    // keep tight bins available for small items).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-full placements (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible item can fill (items >= 1, but typical min 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 2.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins tighter than average are more valuable to preserve space-wise;
    // prefer placing into looser-than-average bins to consolidate tight ones.
    let rel_tight = bin_residual as f64 - mean_residual;
    score += 0.15 * rel_tight;

    // Time horizon: late in the stream, consolidate aggressively (fewer new bins).
    if progress > 0.7 {
        score += 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    // New-bin candidate handling: opening a new bin is costly unless current fit is terrible
    // or no good option exists. Penalize the fresh bin moderately, but less if item is large
    // (large items are hard to place later) or stream is early.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        let early_discount = (1.0 - progress) * 15.0;
        score = bin_capacity as f64 - large_item_bonus - early_discount + 2.0 * open_pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: penalize leftover space, with a non-linear (quadratic) waste curve
    // that grows sharper as the stream progresses (dead space matters more later).
    let mut score = pr + 60.0 * progress * fit_frac * fit_frac;

    // Smooth coupling: reward tight fits more strongly as stream advances.
    let tightness = 1.0 - fit_frac;
    score -= 25.0 * progress * tightness * tightness * tightness;

    // Penalty for creating residuals that can't hold a typical future item,
    // smoothly scaled by mean residual pressure across open bins.
    let mean_fit = mean_residual / cap;
    score += 10.0 * (fit_frac * (1.0 - fit_frac)) * (1.0 - mean_fit.abs());

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item; smooth interaction.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let norm = gap / cap;
        score += 15.0 * norm * norm * (1.0 - progress);
        // Bonus if next item fits exactly-ish into the post residual.
        if pr >= nxt {
            score -= 12.0 * (1.0 - norm * 2.0).max(0.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mild penalty for bin proliferation, smooth in open_bins_count.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish score that scales with stream progress,
    // so early on we prefer filling open bins, later a fresh bin is viable
    // when open-bin scores are bad.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residuals in awkward harmonic classes are hard to fill.
    // Classes near 0 (perfect fit) are great; classes in the "gap" (1..9, 11..19) are bad.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is the best outcome
    } else if post_residual < 10 {
        score += 25.0 + 2.5 * (10 - post_residual) as f64; // tiny unusable sliver
    } else if r10 == 0 {
        score -= 8.0; // harmonic class: divisible by 10, easy to fill with small items
    } else if r25 == 0 {
        score -= 6.0; // divisible by 25 class
    } else if r10 >= 5 {
        score += 4.0; // mid-range residue, moderately awkward
    } else {
        score += 7.0; // small residue, worst class
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how well next item packs the remainder
            let slack = (post_residual - next_item_size) % 10;
            score -= 10.0 - slack as f64;
        } else {
            // next item won't fit here; penalize proportionally to overflow gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    // or the stream is early and bin pool is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = post_residual < 10;
        let lonely = open_bins_count == 0;
        let mut penalty = 15.0;
        if tight_fit { penalty -= 20.0; }
        if lonely { penalty -= 10.0; }
        if progress < 0.2 { penalty -= 3.0; }
        score += penalty.max(-25.0);
    }

    // Prefer fuller bins: normalize by mean residual across open bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for bins whose residual is in a "friendly" integer-division tier.
    let tier = post_residual / 20; // 0..5 tiers of 20 capacity units
    score += tier as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..10) are nearly useless later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement is great.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap likely wasted relative to lookahead
    }

    // New-bin candidate: prefer it only when current bins are badly fragmented
    // (mean residual small relative to item) or the item barely fits an open bin.
    if bin_residual == bin_capacity {
        let tight_fit = bin_residual - item_size <= 5;
        let fragmented = mean_residual < item_size as f64 * 0.5;
        if tight_fit || fragmented {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

