    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate (pristine empty bin): default penalty so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow a new bin if existing fitting bins are all terrible
        // (large dead space would result) or none besides this fit.
        if post_residual > 0 && next_item_size > post_residual as u32 {
            score -= 100.0;
        }
    }

    // Mild pressure to fill bins deeper as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Discard tiny fraction to break ties toward tighter bins.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit and post residual is small, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a bin is cheap when many bins exist and residuals are fragmented.
        let open_bonus = (open_bins_count as f64).ln().max(0.0) * 5.0;
        score = 40.0 + 20.0 * (1.0 - progress) + 30.0 * fragmentation - open_bonus;
        // If nothing else fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items prefer a fresh bin when mean residual is small.
        if item_size >= 70 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Slight preference for bins below mean residual (balance spreading).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr + 60.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: penalize waste more as stream advances
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: cubic term in (item/capacity)
    let tight = item_size as f64 / cap;
    score -= 40.0 * tight * tight * tight;

    // Dead-space penalty: post_residual too small to fit typical items is bad
    let dead = ((20.0 - norm_pr * cap) / 20.0).max(0.0);
    score += 25.0 * dead * dead * (1.0 + progress);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            score -= 15.0 * (1.0 - (next / cap)) * (1.0 + progress);
        } else {
            score += 10.0 * ((next - pr) / cap) * (1.0 + progress);
        }
    }

    // Mild pressure from open bins: more open bins -> prefer filling existing
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual deviation: prefer bins near mean residual (keeps balance)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) + 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                bonus += 6.0;
            }
        }
        score -= bonus;
        // Very small dead space is excellent (near-perfect fill)
        if pr <= 5 {
            score -= 15.0;
        } else if pr < 10 {
            score -= 8.0;
        }
        // Dead zone: leftovers that almost nothing can use (1..10 already handled;
        // awkward mid-zones like 11..14 or 26..29 are hard to fill)
        if (11..=14).contains(&pr) || (26..=29).contains(&pr) || (41..=44).contains(&pr) {
            score += 10.0;
        }
    } else {
        // Perfect fit
        score -= 40.0;
    }

    // Integer-division thresholds: which harmonic "slot" the post residual lives in
    let slot = pr / 25; // 0..=4 quarter classes
    score += match slot {
        0 => -5.0,
        1 => 0.0,
        2 => 3.0,
        3 => 6.0,
        _ => 10.0,
    };

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 12.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item cannot use this bin's leftover; penalize big leftovers
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when the item
    // is large relative to capacity or open-bin leftovers are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // large items -> new bin is fine; small items -> prefer filling open bins
        let bias = 25.0 * (item_frac - 0.5) * 2.0 + 10.0 * (1.0 - progress);
        score += 20.0 - bias;
        if mean_residual < item_size as f64 {
            score -= 15.0; // no open bin has room anyway
        }
    }

    // Mild pressure to consolidate when too many bins are open
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.3;
    }

    // Tie-break toward bins below mean residual (smaller leftovers preferred)
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear tightness bonus.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;

        // Lookahead: exact fit for next item is gold; near-fit scaled.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 80.0;
            } else if next_item_size <= post_residual {
                let slack = (post_residual - next_item_size) as f64;
                score -= 55.0 + 0.4 * next_item_size as f64 - 0.25 * slack;
            } else {
                let gap = (next_item_size - post_residual) as f64;
                score += 0.4 * gap.min(50.0);
            }
        }

        // Dead space penalty: residuals too small for typical items.
        if post_residual < 10 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 40.0 * (1.0 - progress);
        }
    }

    // Prefer bins below mean residual: keep tight bins for small items.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin when only one option exists.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: expensive unless scarcity justifies it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut open_score = 45.0 + 15.0 * (1.0 - progress) + 25.0 * fragmentation
            - (open_bins_count as f64).min(12.0) * 1.5;
        // Large items prefer fresh bins when residuals are too small for them.
        if item_size >= 70 && mean_residual < item_size as f64 {
            open_score -= 20.0;
        }
        // If next item also needs a fresh bin, opening now amortizes.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            open_score -= 12.0;
        }
        if fitting_bins_count == 0 {
            open_score -= 200.0;
        }
        score = open_score;
    }

    // Mild consolidation pressure.
    score += (open_bins_count as f64).sqrt() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Lookahead: reward if the next item fits into the post residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            // Scale lookahead bonus with remaining stream: early steps benefit more.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= (60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste) * (1.0 + 0.5 * (1.0 - progress));
        } else if next_item_size > 0 {
            // Next item won't fit here: penalize dead space relative to next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }

        // Penalize small unusable residuals (dead space), worse mid-stream.
        if post_residual < 10 {
            score += 25.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Prefer bins below mean residual (use emptier bins for big items,
    // keep tight bins available for small items).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: attractive only when the item is a poor fit everywhere
    // (few fitting bins) or the next item is large and would be stranded.
    if bin_residual == bin_capacity {
        let next_strand = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let scarcity = (fitting_bins_count as f64).min(4.0);
        // Scarcity term: with 1 fitting bin the new-bin option becomes tempting;
        // with many fitting bins, strongly discourage opening a new one.
        score += 30.0 - 15.0 * next_strand - 6.0 * scarcity - (open_bins_count as f64).min(10.0);
        // Big item in a mostly-full fleet: opening fresh space can be worth it.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
