            let progress = 1.0 - step_index as f64 / total_items.max(1) as f64;
            score -= 70.0 + 0.6 * next_item_size as f64 - 0.45 * lookahead_waste
                     + 20.0 * progress * (1.0 - lookahead_waste / bin_capacity as f64);
        } else if next_item_size > 0 {
