        if post_residual < 10 {
            score += 25.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }

        // NEW: penalize residuals that no plausible future item can use.
        // If the residual is smaller than the next item and very small overall,
        // it is likely dead space for the rest of the stream.
        if post_residual < next_item_size && post_residual < 6 {
            score += 15.0 + post_residual as f64;
        }
