    // Additional coupling: opening a bin is cheaper when many bins are open
    // (fragmentation risk is low) and the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let large_item_pull = (item_size as f64 / bin_capacity as f64) * 10.0;
        score += 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                 - large_item_pull;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
