    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 25.0 * tightness * tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if lookahead_waste > 0 && next_item_size > 0 && lookahead_waste >= next_item_size as f64 {
                score -= 8.0 * (1.0 - progress);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }

        if post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
        }

        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let dead_ratio = post_residual as f64 / bin_capacity as f64;
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 4.0 * dead_ratio * 10.0 + 0.15 * mean_gap.min(30.0);
        }

        let post_frac = post_residual as f64 / bin_capacity as f64;
        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        }

        // NEW: dead-space ratio penalty — residuals that can never host
        // typical items are pure waste; scale by how much of the bin is dead.
        if post_residual > 0 && next_item_size > post_residual {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            score += 18.0 * dead_frac * (1.0 + 0.4 * (1.0 - progress));
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
        }
        if progress > 0.8 && next_item_size > bin_capacity - item_size {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if next_fits_new && item_size + next_item_size < bin_capacity / 2 {
            new_score += 8.0 * (1.0 - progress);
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if next_fits_new && fitting_bins_count <= 3 {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
        }
        score += new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 25.0 * tightness * tightness) * (1.0 + 0.3 * (1.0 - progress));
            // Extra reward when the residual after placing next item is nearly zero.
            if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: after placing next item, can a third item still fit?
            if lookahead_waste > 0 && next_item_size > 0 && lookahead_waste >= next_item_size as f64 {
                score -= 8.0 * (1.0 - progress);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }

        if post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
        }

        // Residual just barely above next item: tempting but wasteful.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Dead-space guard: penalize residuals too small for the next item,
        // scaled by how far below mean residual this bin would end up.
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_ratio = post_residual as f64 / bin_capacity as f64;
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 4.0 * dead_ratio * 10.0 + 0.15 * mean_gap.min(30.0);
            // New: dead-space penalty grows when many bins compete — pick the
            // bin whose leftover is least likely to strand.
            if fitting_bins_count >= 3 {
                score += 3.0 * (fitting_bins_count.min(8) as f64 - 2.0) * (1.0 - progress);
            }
        }

        // Reward placements that push the bin close to a perfectly packed
        // multiple of typical item sizes: near-zero post residual relative
        // to bin capacity is compaction gold.
        let post_frac = post_residual as f64 / bin_capacity as f64;
        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        }

        // New: graded compaction reward — the closer post_residual is to the
        // smallest possible leftover, the better. Use a soft quadratic ramp
        // on post_frac across the whole range, not just the extreme tail.
        score += 6.0 * post_frac * post_frac * (1.0 - progress);
    }

    // Prefer bins below mean residual; damp late-stream.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        // Fresh bin should ideally host item + next item with minimal leftover.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
        }
        if progress > 0.8 && next_item_size > bin_capacity - item_size {
            new_score += 15.0;
        }
        // Big item in a mostly-full fleet: opening fresh space can be worth it.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        // Two-item lookahead: avoid squandering fresh space on low-fill openings.
        if next_fits_new && item_size + next_item_size < bin_capacity / 2 {
            new_score += 8.0 * (1.0 - progress);
        }
        // Late-stream: opening new bins is costly; make fresh bins less attractive.
        if progress > 0.85 {
            new_score += 10.0;
        }
        // With many open bins, prefer fitting into existing space.
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        // If the fresh bin would host item + next with near-zero waste
        // and few fitting bins exist, open it decisively.
        if next_fits_new && fitting_bins_count <= 3 {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
        }
        // New: if the item is large and no open bin fits it well, opening a
        // fresh bin keeps the fleet's small residuals intact for small items.
        if item_size as f64 > 0.4 * bin_capacity as f64
            && open_bins_count >= 4
            && next_item_size > 0
            && next_item_size > bin_capacity - item_size
        {
            new_score -= 6.0 * (1.0 - progress);
        }
        score += new_score;
    }

    score
}

