            let tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 25.0 * tightness * tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Exact fit of next item: strongest compaction signal.
            if lookahead_waste == 0.0 {
                score -= 22.0;
            }
            // Chain lookahead: leftover after next item can host a third item?
            if lookahead_waste > 0.0 && lookahead_waste >= next_item_size as f64 {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }

        if post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
        }

        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Dead-space guard with mean-gap scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_ratio = post_frac;
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 4.0 * dead_ratio * 10.0 + 0.15 * mean_gap.min(30.0);
            // Severely undersized residual (less than half of next item) is
            // almost certainly dead space: penalize harder early on.
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 9.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - dead_ratio);
            // Residual that can't host even the smallest plausible item
            // (anything <= 100) is pure dead weight: strong penalty.
            if post_residual < 12 {
                score += 6.0 * (12.0 - post_residual as f64) / 12.0;
            }
        }

        // Compaction rewards: near-full residuals in the 0-10% band.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Mid-band awkwardness: 10-25% residuals unlikely to host anything.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second fit reward, scaled by scarcity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            // Moderate slack that still leaves a hostable remainder (< 25)
            // is a good double-fit: mild reward to prefer it over fragmenting.
            else if slack < 25.0 {
                score -= 3.0 * (1.0 - slack / 25.0) * (1.0 + 0.3 * (1.0 - progress));
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                // Perfect pair: item + next exactly fill a fresh bin.
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            // Perfect pair bonus when few fitting bins exist.
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            // Fresh bin valuable when no open bin can host item+next pair.
            let best_pair = (mean_residual - item_size as f64).max(0.0);
            if best_pair < next_item_size as f64 && pair_waste < 15.0 {
                new_score -= 10.0 * (1.0 - pair_waste / 15.0);
            }
            // Large item with no tight open fit: fresh bin avoids fragmenting.
            if fitting_bins_count >= 1 && item_size as f64 > 0.45 * bin_capacity as f64 {
                let tightest = (mean_residual - item_size as f64).max(0.0);
                if tightest > 0.2 * bin_capacity as f64 {
                    new_score -= 6.0 * (1.0 - progress);
                }
            }
            // Two-item lookahead in fresh bin: room for a third smaller item
            // reduces the penalty of opening a new bin.
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
        }
        if progress > 0.8 && next_item_size > bin_capacity - item_size {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if next_fits_new && item_size + next_item_size < bin_capacity / 2 {
            new_score += 8.0 * (1.0 - progress);
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        // Early phase: discourage bin proliferation while many items remain
        // and alternatives exist.
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        // Mid-stream: if the current best open-bin fit would strand a
        // residual smaller than the typical next item, a fresh bin whose
        // pair waste is modest is preferable.
        if progress >= 0.25 && progress <= 0.8 && next_fits_new && fitting_bins_count >= 1 {
            let best_fit_left = (mean_residual - item_size as f64).max(0.0);
            if best_fit_left > 0.0 && best_fit_left < next_item_size as f64
                && (bin_capacity - item_size - next_item_size) < best_fit_left {
                new_score -= 8.0 * (1.0 - progress);
            }
        }
        score += new_score;
    }

    score
}

