                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            // Fresh bin valuable when no open bin can host item+next pair.
            let best_pair = (mean_residual - item_size as f64).max(0.0);
            if next_strand > 0.0 && best_pair < next_item_size as f64 && pair_waste < 15.0 {
                new_score -= 10.0 * (1.0 - pair_waste / 15.0);
            }
            if pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
        }
