    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
