        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        // NEW: penalize opening a bin when the item would leave a very
        // hostable residual in an existing bin (dead-space avoidance).
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
