    // post-residual is awkwardly between small usable gaps and comfortable
    // room, since such gaps rarely get filled (dead-space reduction).
    if post_residual > 0 && post_residual < bin_capacity {
        let awkward_zone = post_residual as f64 >= 20.0 && post_residual as f64 <= 34.0;
        if awkward_zone {
            let depth = 1.0 - ((post_residual as f64 - 27.0).abs() / 7.0);
            score += 6.0 * depth * (1.0 - progress);
        }
        // Reward residuals that are "harmonic" — likely to be exactly filled
        // by common small items (residual divisible into small chunks).
        if post_residual % 5 == 0 || post_residual % 10 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Global tightness reward (borrowed from best): prefer near-full placements.
        let tightness = 1.0 - post_frac;
        score -= 12.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let tight = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 25.0 * tight * tight) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if lookahead_waste == 0.0 {
                score -= 20.0;
            }
            // Chain lookahead: leftover after next item can host a third item
            if lookahead_waste > 0.0 && (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
        }

        if post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        } else if post_residual < 20 {
            score += 8.0;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
        }

        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Dead-space guard with mean-gap scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 4.0 * post_frac * 10.0 + 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Compaction rewards: near-full residuals in the 0-10% band.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Residual far below fleet mean is good (consolidation signal).
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Mid-band awkwardness: 10-25% residuals unlikely to host anything.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second fit reward, scaled by scarcity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
