            score += 10.0 * (0.5 - fill_ratio);
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: prefer reusing existing bins as fleet grows.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            // Refuse fresh bin whose pair-waste exceeds achievable mean residual.
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Refuse fresh bin when an existing bin's post-fit residual is near-perfect.
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        // Existing bin can host the next item too: keep it open.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        // Fresh-bin waste forecast vs typical open-bin residuals.
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        // Opening attractive when fleet fragmented and item is big.
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        // Avoid opening fresh bins late when fragmentation is low.
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        // Mid-stream guard: opening a bin that leaves residual below mean is a loss.
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        // Perfect fit: very strong reward, amplified late when bins are precious.
        score -= 900.0 + 60.0 * progress;
    } else {
        // Tightness reward: strongly prefer near-full placements.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        // Dead-space avoidance: tiny gaps are nearly useless later.
        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Lookahead: reward placements that leave room for the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (45.0 + 0.35 * next_item_size as f64
                     + 20.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if waste == 0.0 {
                score -= 20.0;
            }
            // Chain lookahead: leftover after next item can host a third item.
            if waste > 0.0 && (waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                // Deep chain: after the next item, leftover still hosts another.
                let after = waste - next_item_size as f64;
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
            }
        } else if next_item_size > 0 {
            // Gap likely wasted relative to lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            // Near-miss penalty: small gap is almost certainly dead space.
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            // NEW: if the gap is smaller than the fleet mean residual, this
            // leftover is likely unusable while other bins could absorb it.
            if (post_residual as f64) < mean_residual && gap <= mean_residual {
                score += 2.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
            }
        }

        // Residual vs. mean coupling: post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let mut new_score = 30.0
            - (open_bins_count as f64).min(10.0)
            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            // Refuse fresh bin whose pair-waste exceeds achievable mean residual.
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        // Big item with few fitting bins: opening is attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Refuse fresh bin when an existing bin's post-fit residual is near-perfect.
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        // Existing bin can host the next item too: keep it open.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        // Fresh-bin waste forecast vs typical open-bin residuals.
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        // Opening attractive when fleet fragmented and item is big.
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        // Avoid opening fresh bins when the stream is nearly done and
        // residual fragmentation is low — remaining items likely fit elsewhere.
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        // Mid-stream guard: if the current best existing-bin fit leaves a
        // residual smaller than the mean residual, opening a new bin is a loss.
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        // NEW: endgame guard — late in the stream, remaining items are few;
        // opening a fresh bin should only happen if no existing bin fits well.
        if progress > 0.85 && fitting_bins_count >= 2 {
            new_score += 5.0 * (fitting_bins_count as f64).min(3.0);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

