        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            // Reusable-slack sweet spot: residual that can host the next item
            // AND still roughly matches mean residual stays flexible.
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus — residuals that are exact multiples of the
        // next item size will tile perfectly with repeated future items,
        // eliminating dead space entirely.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // hostability index — reward residuals that lie just above a
        // plausible future item size (near mean residual), penalize residuals
        // that fall in the "dead zone" just below the mean residual, where
        // typical items cannot land but the space is too big to ignore.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                // dead zone: just under typical future item size
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                // large leftovers: only good if near-multiple of mean residual
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // NEW: scarcity-tiling bonus — when few bins can host the item, a
        // residual that tiles with the next item size multiple times is a
        // rare commodity; reward it proportionally to scarcity.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let tiles = post_residual / next_item_size;
            if tiles >= 2 {
                score -= 2.5 * (fitting_bins_count.max(1) as f64).recip().min(1.0)
                         * (1.0 - progress) * (tiles as f64).min(3.0) / 3.0;
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            let best_pair = (mean_residual - item_size as f64).max(0.0);
            if best_pair < next_item_size as f64 && pair_waste < 15.0 {
                new_score -= 10.0 * (1.0 - pair_waste / 15.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            // Fresh-bin pair-waste near mean residual means the leftover stays
            // hostable by typical future items — discourage large outliers.
            if pair_waste > 0.0 && (pair_waste as f64).abs() - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            // pair-waste just below mean residual is near-permanent dead
            // space (typical items won't fit) — penalize opening such bins.
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.45 * bin_capacity as f64 {
            let tightest = (mean_residual - item_size as f64).max(0.0);
            if tightest > 0.2 * bin_capacity as f64 {
                new_score -= 6.0 * (1.0 - progress);
            }
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if next_fits_new && item_size + next_item_size < bin_capacity / 2 {
            new_score += 8.0 * (1.0 - progress);
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        // When the existing-bin pool is thin and the item is large,
        // opening a fresh bin preserves compactness for the endgame.
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 25.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if lookahead_waste == 0.0 {
                score -= 20.0;
            }
            // Chain lookahead: leftover after next item can host a third item
            if lookahead_waste > 0.0 && (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                let after = lookahead_waste - next_item_size as f64;
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            // Dead-space killer: residuals matching the typical next-item size band
            // stay hostable by future small items.
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress) * (1.0 - ((post_residual as f64) - mean_residual).abs() / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
            // GEN22: two-item chain bonus — if the post residual can host the next
            // item AND the remainder can host the item after that, this bin
            // eliminates two future placements; scale with early-stream pressure.
            if fitting_bins_count > 2 && lookahead_waste >= next_item_size as f64 {
                let chain_depth = (lookahead_waste / next_item_size as f64).floor().min(3.0);
                score -= 4.0 * chain_depth * (1.0 - progress) * (1.0 - post_frac);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            // Penalize stranded residuals whose gap exceeds the observed
            // mean residual spread — likely permanent dead space.
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            // GEN22: sharpen the near-miss penalty — residuals within a hair of
            // hosting the next item are the most frustrating dead space.
            if gap <= 3.0 {
                score += 6.0 * (1.0 - gap / 3.0) * (1.0 + 0.5 * (1.0 - progress));
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 4.0 * post_frac * 10.0 + 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            // Reusable-slack sweet spot: residual that can host the next item
            // AND still roughly matches mean residual stays flexible.
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus — residuals that are exact multiples of the
        // next item size will tile perfectly with repeated future items,
        // eliminating dead space entirely.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index — reward residuals just above a plausible future
        // item size, penalize residuals in the "dead zone" just below it.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                // GEN22: dead zone — widen and deepen; this is the diagnosed
                // weakness, so weight it more as the stream matures.
                let dz = (1.0 - (1.0 - rel) / 0.45).max(0.0);
                score += 5.0 * (1.0 + 0.4 * progress) * dz;
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            let best_pair = (mean_residual - item_size as f64).max(0.0);
            if best_pair < next_item_size as f64 && pair_waste < 15.0 {
                new_score -= 10.0 * (1.0 - pair_waste / 15.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            // Fresh-bin pair-waste near mean residual means the leftover stays
            // hostable by typical future items — discourage large outliers.
            if pair_waste > 0.0 && (pair_waste as f64).abs() - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            // Pair-waste just below mean residual is near-permanent dead
            // space (typical items won't fit) — penalize opening such bins.
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            // GEN22: prefer fresh-bin leftovers that tile with the mean
            // residual — if pair waste is a near-exact multiple of the
            // typical future item, the new bin stays fully recoverable.
            if pair_waste > 0.0 && mr > 1.0 {
                let q = (pair_waste / mr).round();
                if q >= 1.0 && (pair_waste - q * mr).abs() <= 2.0 {
                    new_score -= 5.0 * (1.0 - progress);
                }
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.45 * bin_capacity as f64 {
            let tightest = (mean_residual - item_size as f64).max(0.0);
            if tightest > 0.2 * bin_capacity as f64 {
                new_score -= 6.0 * (1.0 - progress);
            }
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if next_fits_new && item_size + next_item_size < bin_capacity / 2 {
            new_score += 8.0 * (1.0 - progress);
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        // When the existing-bin pool is thin and the item is large,
        // opening a fresh bin preserves compactness for the endgame.
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 25.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if lookahead_waste == 0.0 {
                score -= 20.0;
            }
            // Chain lookahead: leftover after next item can host a third item
            if lookahead_waste > 0.0 && (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                let after = lookahead_waste - next_item_size as f64;
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            // Dead-space killer: residuals matching the typical next-item size band
            // stay hostable by future small items.
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress) * (1.0 - ((post_residual as f64) - mean_residual).abs() / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            // Penalize stranded residuals whose gap exceeds the observed
            // mean residual spread — likely permanent dead space.
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            // NEW: near-miss residuals (gap within a few units of the next item)
            // are one small item away from being usable — mild extra penalty
            // only if few alternatives exist, otherwise steer away gently.
            if gap > 0.0 && gap <= 3.0 && fitting_bins_count > 2 {
                score += 1.5 * (1.0 - gap / 3.0) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 4.0 * post_frac * 10.0 + 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            // Reusable-slack sweet spot: residual that can host the next item
            // AND still roughly matches mean residual stays flexible.
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus — residuals that are exact multiples of the
        // next item size will tile perfectly with repeated future items,
        // eliminating dead space entirely.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index — reward residuals just above a plausible future
        // item size (near mean residual), penalize the "dead zone" just below
        // the mean residual, where typical items cannot land.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                // dead zone: just under typical future item size
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                // large leftovers: only good if near-multiple of mean residual
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
            // NEW: perfect-fill coupling — residual exactly equal to the next
            // item size means zero dead space after the next placement; this
            // is the strongest compaction signal available, reward harder
            // when few bins remain hostable.
            if next_item_size > 0 && post_residual == next_item_size {
                let scarcity_w = if fitting_bins_count <= 3 { 1.8 } else { 1.0 };
                score -= 10.0 * scarcity_w * (1.0 + 0.3 * (1.0 - progress));
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            let best_pair = (mean_residual - item_size as f64).max(0.0);
            if best_pair < next_item_size as f64 && pair_waste < 15.0 {
                new_score -= 10.0 * (1.0 - pair_waste / 15.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            // Fresh-bin pair-waste near mean residual means the leftover stays
            // hostable by typical future items — discourage large outliers.
            if pair_waste > 0.0 && (pair_waste as f64).abs() - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            // Pair-waste just below mean residual is near-permanent dead
            // space (typical items won't fit) — penalize opening such bins.
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            // NEW: pair-waste that is itself an exact multiple of the next
            // item size tiles cleanly with future repeats — discourage
            // opening bins whose waste resists tiling.
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size != 0
                && pair_waste < 2.0 * next_item_size as f64 {
                new_score += 2.0 * (1.0 - progress) * (1.0 - pair_waste / (2.0 * next_item_size as f64));
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.45 * bin_capacity as f64 {
            let tightest = (mean_residual - item_size as f64).max(0.0);
            if tightest > 0.2 * bin_capacity as f64 {
                new_score -= 6.0 * (1.0 - progress);
            }
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if next_fits_new && item_size + next_item_size < bin_capacity / 2 {
            new_score += 8.0 * (1.0 - progress);
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        // When the existing-bin pool is thin and the item is large,
        // opening a fresh bin preserves compactness for the endgame.
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Tightness reward: strongly prefer near-full placements.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            // Exact pair: near-perfect compaction.
            if lookahead_waste == 0.0 {
                score -= 20.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item.
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                // Divisibility: residual tiles perfectly with repeated items.
                if post_residual % next_item_size == 0 {
                    score -= 6.0 * (1.0 - progress);
                }
            }
            // Residual matching the mean-residual band stays hostable.
            let mr = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            // Near-miss: dead space almost certainly.
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            // Stranded residual: likely permanent dead space.
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
            // Below-mean residuals are hard to host: penalize proportionally.
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Residual just barely above next item: tempting but wasteful.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            score += 10.0 * (0.5 - fill_ratio);
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Tiny residual bonus: near-closed bins are excellent.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: prefer reusing existing bins as fleet grows.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            // Refuse fresh bin whose pair-waste exceeds achievable mean residual.
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            // Pair-waste just below mean residual is near-permanent dead space.
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Refuse fresh bin when an existing bin's post-fit residual is near-perfect.
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        // Existing bin can host the next item too: keep it open.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        // Fresh-bin waste forecast vs typical open-bin residuals.
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        // Opening attractive when fleet fragmented and item is big.
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        // Avoid opening fresh bins late when fragmentation is low.
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        // Mid-stream guard: opening a bin that leaves residual below mean is a loss.
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        // Thin pool + large item: open fresh bin to preserve endgame compactness.
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

