        score -= 1000.0 + 60.0 * progress;
    } else {
        // Global tightness reward: prefer near-full placements.
        let tightness = 1.0 - post_frac;
        score -= 28.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
