            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 20.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis.
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual guard.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 20.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
