                if (post_residual as u32) >= 2 * next_item_size {
                    let twice_waste = (post_residual as u32) % (2 * next_item_size);
                    if twice_waste == 0 {
                        score -= 9.0 * (1.0 - progress);
                    } else if twice_waste <= 3 {
                        score -= 4.0 * (1.0 - twice_waste as f64 / 3.0) * (1.0 - progress);
                    }
