            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard with stream-length scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Fresh bin loses when the existing residual is already compact or chainable.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Fine-grained residual tightness reward (combined feature).
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let tight = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (58.0 + 0.45 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 24.0 * tight * tight) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard: penalize residuals too small for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual % 10 == 0 {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
        if post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
    }

    // Prefer bins below mean residual; damp late-stream.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 7.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Fresh bin unattractive when an existing bin has near-perfect residual.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // NEW: prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // NEW: tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr;
            let near_mean_mult = ((rel - rel.round()).abs() * mr) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // NEW: when the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize small dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it, else it's wasted capacity.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted fit potential.
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Prefer filling bins whose residual is below the mean residual (consolidating waste).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be pickier about opening new bins;
    // late in the stream, just pack anything that fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty that grows with number of open bins,
        // reduced late in the stream when consolidation matters less.
        score = 30.0 + 4.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
        // If nothing else fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else if progress > 0.8 {
        score -= 10.0; // endgame: favor existing bins even more
    }

    // Slight preference for bins with larger residuals when item is small
    // (keep small residuals for larger future items).
    if item_size < 30 {
        score += 0.2 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: strong compaction pressure — reward very high fill ratios harder.
        if fill_ratio >= 0.85 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0 * (fill_ratio - 0.85) / 0.15 * (1.0 + 0.5 * progress);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // NEW: refuse new bins when the existing residual can host item+next chain.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_slack = post_residual - next_item_size;
            if chain_slack >= item_size.min(next_item_size) {
                new_score += 12.0 * (1.0 - progress);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 1.5 * progress * progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - base).powi(3) * (2.0 + 3.0 * progress);

    // Penalize large dead space quadratically
    score += base * base * 2.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Penalize opening a new bin, especially early in the stream
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 1.5 + 2.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.5 * (next_item_size as f64 / cap);
    }

    // Mild penalty proportional to mean residual to prefer bins with less waste
    score += 0.3 * mean_residual / cap;

    // Prefer placing into already-open bins
    if bin_residual < bin_capacity {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: dead-space compaction term — reward bins whose post-residual can
        // still host a plausible fraction of the mean residual, penalize those
        // whose dead space is an awkward sliver relative to fleet mean.
        if post_residual > 0 {
            let dead = post_residual as f64;
            let sliver = dead / mr;
            if sliver < 0.35 {
                score += 5.0 * (0.35 - sliver) * (0.4 + 0.6 * progress);
            } else if sliver <= 1.0 {
                score -= 2.5 * (1.0 - sliver) * (1.0 - progress);
            }
        }
        // NEW: reward filling bins that are close to capacity overall —
        // pushes residual variance down by "closing out" nearly-full bins.
        if fill_ratio >= 0.9 {
            score -= 8.0 * (fill_ratio - 0.9) / 0.1 * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr;
            let near_mean_mult = ((rel - rel.round()).abs() * mr) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // NEW: refuse fresh bins harder when the existing residual is itself a
        // small, soon-usable sliver (post_residual below next item but within a
        // few units) — those gaps close quickly with upcoming small items.
        if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
            let gap = next_item_size - post_residual;
            if gap <= 6 {
                new_score += 5.0 * (1.0 - gap as f64 / 6.0) * (1.0 + 0.5 * (1.0 - progress));
            }
        }
        // NEW: late-stream, allow new bins more freely to avoid fragmentation
        // of the remaining open-bin residuals.
        if progress > 0.9 && next_fits_new && open_bins_count > 4 {
            new_score += 4.0 * ((open_bins_count - 4) as f64).min(6.0);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of 10, or small enough to still accept mid items)
    // get rewarded; awkward dead-space classes get penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 8.0; // clean reusable class
    } else if pr < 10 {
        score += 5.0; // tiny dead space, nearly closed
    } else {
        score += ((pr % 10) as f64) * 0.6; // ragged leftover penalty
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // chains the next item nicely
            // harmonic match: next item lands on a clean class boundary
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else if next_item_size <= bin_residual && next_item_size > pr {
            score += 10.0; // we consume space the next item needed
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins with slack: prefer tight fills to consolidate.
    if open_bins_count > 4 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 6.0 * ((open_bins_count as f64).ln() + 1.0);
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // filling it helps equalize residuals.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual + 30.0;
        if poor_fit_everywhere {
            score -= 25.0;
        } else {
            score += 15.0; // discourage wasting a fresh bin
        }
    }

    // Late stream: consolidate harder as we approach the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: bins with post_residual in the
    // "half-bin or less" zone are worth closing out.
    if pr <= bin_capacity / 2 && pr > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: stronger finishing bias — a residual that is exactly half (or a
        // small divisor) of the next item's size tiles into a perfect fill later.
        if next_item_size > 0 && next_item_size > post_residual {
            if next_item_size % post_residual == 0 && post_residual > 0 {
                let q = next_item_size / post_residual;
                score -= 3.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }
        // NEW: dead-space-aware squeeze — when the fleet is crowded, favor bins
        // whose post-residual is small relative to the fleet mean (compactness).
        if open_bins_count > 5 && post_residual > 0 {
            let rel_pr = post_residual as f64 / mr;
            if rel_pr < 0.35 {
                score -= 4.0 * (1.0 - progress) * (1.0 - rel_pr / 0.35);
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mrm = mean_residual.max(1.0);
            let rel = post_residual as f64 / mrm;
            let near_mean_mult = ((rel - rel.round()).abs() * mrm) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // NEW: refuse new bins more strongly when the existing residual can host
        // the next item AND the leftover after that still hosts the mean item —
        // a two-step chain that a fresh bin cannot replicate.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            let after2 = post_residual - next_item_size;
            if after2 >= item_size.min(next_item_size) {
                new_score += 10.0 * (1.0 - progress);
            }
            // NEW: also reward when after2 is divisible by the next item (tiled chain).
            if after2 > 0 && next_item_size > 0 && after2 % next_item_size == 0 {
                new_score += 5.0 * (1.0 - progress);
            }
        }
        // NEW: mid-stream, an open bin that leaves post_residual in the "awkward
        // band" (just below mean residual) is a bad trade vs. a fresh bin.
        if post_residual > 0 && (post_residual as f64) < mean_residual
            && (post_residual as f64) > 0.5 * mean_residual && progress < 0.7 {
            new_score -= 4.0 * (1.0 - (post_residual as f64 - 0.5 * mean_residual) / (0.5 * mean_residual));
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
            // NEW: two-step chain — if the item after next also tiles, reward more.
            if fitting_bins_count <= 3 && lookahead_waste >= 2.0 * next_item_size as f64 {
                score -= 6.0 * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.2);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: stronger finishing pressure — bins that would be left with almost
        // nothing after placement are near-complete; reward aggressively.
        if post_residual > 0 && post_residual <= 4 {
            score -= 5.0 * (1.0 - post_residual as f64 / 4.0) * (0.5 + 0.5 * progress);
        }
        // NEW: penalize leaving a residual that is awkwardly just below the
        // next-next size band (dead space diagnosis refinement).
        if next_item_size > 0 && post_residual < next_item_size
            && (post_residual as f64) > 0.8 * mean_residual {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // NEW: refuse fresh bins when an existing fit leaves a residual that can
        // still host the mean-sized item (keeps fleet residuals useful).
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual as f64) >= 0.7 * mean_residual.max(1.0) {
            new_score += 5.0 * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // High-fill bins are close to being finished: squeeze them.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Near-multiple of mean residual is a reusable asset: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Fresh pair-waste stranding more than current post-residual: refuse.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (58.0 + 0.45 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 24.0 * tightness * tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard: penalize residuals too small for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Prefer squeezing into high-fill bins that can still host next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual % 10 == 0 {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
        if post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Prefer bins below mean residual; damp late-stream.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 7.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Fresh bin unattractive when an existing bin has near-perfect residual.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Near-multiple of mean residual is a reusable asset: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rel = post_residual as f64 / mr;
            let near_mean_mult = ((rel - rel.round()).abs() * mr) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Fresh pair-waste stranding more than current post-residual: refuse.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
