                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // MUTATION: sharpen the "finishing" reward — bins one item away from
        // completion should absorb the current item aggressively, scaled by how
        // well the current item plugs the remaining hole.
        if fill_ratio >= 0.85 && next_item_size > 0 && next_item_size <= post_residual {
            let plug = 1.0 - ((post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
            score -= 8.0 * (fill_ratio - 0.85) / 0.15 * plug * (1.0 - progress);
        }
        // MUTATION: penalize leaving a residual that is just barely too small
        // for the *next* item — the worst kind of near-miss dead space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 4.0 {
                score += 9.0 * (1.0 - miss / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            // MUTATION: a fresh bin is only worthwhile if its pair-waste is
            // strictly smaller than what any existing fit would strand. Compare
            // against the best existing post-residual concept via mean residual.
            if pair_waste > 0.0 && pair_waste as f64 > mean_residual {
                new_score += 6.0 * ((pair_waste as f64 - mean_residual) / 8.0).min(2.0) * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // MUTATION: refuse fresh bins harder when the current item is small
        // relative to capacity — small items should almost always go into an
        // existing bin's residual rather than seeding a new bin.
        if (item_size as f64) < 0.35 * bin_capacity as f64
            && fitting_bins_count > 0 && post_residual > 0 {
            new_score += 5.0 * (1.0 - item_size as f64 / (0.35 * bin_capacity as f64)) * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
            // NEW: reward consuming bins whose residual is hard to reuse later
            // (post_residual much smaller than mean residual = consolidation win).
            if (post_residual as f64) < 0.7 * mean_residual && fitting_bins_count >= 2 {
                score -= 3.5 * (1.0 - post_residual as f64 / (0.7 * mean_residual).max(1.0))
                            * (0.5 + 0.5 * progress);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            // NEW: extra penalty when this bin is the *only* one that cannot host
            // the next item among few fits — its residual is nearly stranded.
            if gap <= 15.0 && fitting_bins_count <= 2 {
                score += 2.0 * (1.0 - gap / 15.0) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
            // NEW: residual that still tiles into >=3 copies of next item is a
            // long-run asset; reward proportional to the quotient.
            let q = post_residual / next_item_size;
            if q >= 3 {
                score -= 2.0 * ((q as f64).min(6.0) - 2.0) * (1.0 - progress);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: mid-band fill (0.55–0.75) with a hostable residual is a good
        // consolidation target — reward slightly to drain half-filled bins.
        if fill_ratio >= 0.55 && fill_ratio < 0.75 && next_item_size > 0
            && next_item_size <= post_residual && open_bins_count > 4 {
            score -= 2.5 * (fill_ratio - 0.55) / 0.20 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            // NEW: when the fresh pair-waste would strand more space than the
            // current bin's post-residual, refuse the new bin more firmly.
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rel = post_residual as f64 / mean_residual.max(1.0);
            let near_mean_mult = ((rel - rel.round()).abs() * mean_residual.max(1.0)) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // NEW: refuse new bins harder when many bins can already fit the item —
        // spreading across many open bins wastes consolidation opportunities.
        if fitting_bins_count >= 4 {
            new_score += 2.5 * ((fitting_bins_count - 4) as f64).min(6.0) * (0.4 + 0.6 * (1.0 - progress));
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (58.0 + 0.45 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 24.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard: penalize residuals too small for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Refuse fresh bins when existing residual is a near-multiple of mean residual.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr;
            let near_mean_mult = ((rel - rel.round()).abs() * mr) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Fresh pair-waste stranding more than current post-residual: refuse new bin.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward (tightened to squeeze dead space).
        if post_frac < 0.05 && post_residual > 0 {
            score -= 26.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 8.0 * (1.0 - (post_frac - 0.05) / 0.05);
        } else if post_frac < 0.16 {
            score -= 2.0 * (1.0 - (post_frac - 0.10) / 0.06);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: reward finishing off bins that are nearly full regardless of next item.
        if fill_ratio >= 0.9 && post_residual > 0 {
            score -= 5.0 * (fill_ratio - 0.9) / 0.1 * (1.0 - post_frac / 0.1).max(0.0);
        }
        // NEW: penalize leaving mid-band residual that is neither a multiple of
        // next item nor near the mean — prime dead-space generator.
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size != 0 {
            let rel = post_residual as f64 / mr;
            if rel > 0.3 && rel < 0.85 {
                score += 2.5 * (1.0 - progress) * (0.85 - rel) / 0.55;
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr;
            let near_mean_mult = ((rel - rel.round()).abs() * mr) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // NEW: when the existing bin would end with a residual that can still
        // host a fraction of typical items (post >= ~mean), strongly refuse new bins.
        if next_item_size > 0 && post_residual > 0
            && (post_residual as f64) >= 0.8 * mean_residual.max(1.0)
            && post_residual >= next_item_size {
            new_score += 5.0 * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (58.0 + 0.45 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 24.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard: penalize residuals too small for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual % 10 == 0 {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 7.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
            if (post_residual - next_item_size) <= 4 {
                new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
            }
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        // Near-multiple of mean residual is a reusable asset: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rel = post_residual as f64 / mr;
            let near_mean_mult = ((rel - rel.round()).abs() * mr) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - progress);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap <= 10.0 && next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 2.5 * (1.0 - gap / 10.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && (slack as f64) >= 0.5 * mean_residual {
                score -= 2.5 * (1.0 - progress) * ((slack / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Chainable asset under scarcity.
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Penalize dead space proportional to how much of it is stranded.
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into bins whose fill ratio is already high even if
        // post_residual is large — high-fill bins are close to being "finished".
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // NEW: dead-space-ratio gradient — the lower the post_residual fraction,
        // the better the compaction; reward sub-2% residuals more aggressively.
        if post_frac < 0.02 && post_residual > 0 {
            score -= 10.0 * (1.0 - post_frac / 0.02) * (1.0 + 0.5 * progress);
        }
        // NEW: penalize residuals in the "twilight band" that are too small for
        // typical future items (below mean) but not tiny enough to be near-zero.
        if post_residual > 0 && (post_residual as f64) < 0.35 * mean_residual {
            let twilight = 1.0 - post_residual as f64 / (0.35 * mean_residual);
            score += 4.0 * twilight * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > 0.0 && pair_waste >= 8.0 && (pair_waste as u32) >= next_item_size / 2 {
                new_score += 0.2 * pair_waste.min(20.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && next_item_size > 0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && (pair_waste as f64) >= 1.1 * mean_residual && mean_residual >= 3.0 {
                new_score += 2.0 * ((pair_waste as f64) / mean_residual.max(1.0)).min(3.0) * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            // NEW: reject fresh bins whose pair-waste lands in the twilight band
            // (unusable dead space that will likely never be reclaimed).
            if pair_waste > 0.0 && (pair_waste as f64) < 0.35 * mean_residual.max(1.0) {
                new_score += 5.0 * (1.0 - pair_waste / (0.35 * mean_residual.max(1.0)));
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        // NEW: refuse fresh bins even harder when the existing residual can host
        // the next item AND the fleet is already crowded — consolidation wins.
        if next_fits_new && next_item_size > 0 && post_residual >= next_item_size && open_bins_count > 4 {
            new_score += 4.0 * ((open_bins_count - 4) as f64).min(6.0) * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (58.0 + 0.45 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 24.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Global tightness term: reward near-full bins.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));

            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }

            // Chain lookahead: after next item, residual still hosts item_size.
            let chain_left = post_residual - next_item_size;
            if chain_left >= item_size && item_size > 0 {
                score -= 8.0 * (1.0 - progress);
                let after = (chain_left - item_size) as f64;
                if after < item_size as f64 {
                    score -= 8.0 * (1.0 - after / item_size.max(1) as f64);
                }
                let rem = chain_left % item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                }
            }
            // Divisibility of post-residual by next item tiles perfectly.
            if (lookahead_waste as u32) >= next_item_size {
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - post_frac.max(0.05) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space penalty when residual cannot host the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Slack just above next item is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        // Prefer squeezing into high-fill bins that can host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25;
        }
        // Harmonic residual sizes tile well.
        if post_residual % 10 == 0 {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
    }

    // Prefer bins below mean residual; damp late-stream.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        // Fresh bin should host item + next item with minimal leftover.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        // Big item in a mostly-full fleet: opening fresh space can be worth it.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Existing bin leaves a chainable residual: refuse the fresh bin.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Existing residual near a multiple of mean residual is a reusable asset.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            if ((rel - rel.round()).abs() * mr2) <= 2.0 && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Existing bin would strand more than fresh pair-waste: allow opening.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        // High mean residual: fresh bin absorbs overflow cheaply.
        if mean_residual > 0.35 * bin_capacity as f64 {
            new_score -= 6.0;
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (60.0 + 0.5 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 25.0 * tightness * tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Residual that cannot host anything near the mean residual is dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when an existing bin would be left with a
        // residual that is a near-multiple of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // When the fresh pair-waste would strand more space than the current
        // bin's post-residual, refuse the new bin more firmly.
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

