        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual % 10 == 0 {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
        if post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // Exact-fill drive: item exactly consumes the residual.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        // Residual hostable by mean-sized future items is an asset.
        if (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Prefer bins below mean residual; damp late-stream.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 7.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Fresh bin unattractive when an existing bin has near-perfect residual.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Tighten new-bin refusal when residual is a near-multiple of mean residual.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Refuse fresh bins when an existing bin achieves an exact fit.
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        // Refuse fresh bins when the existing residual can chain-host next item twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        // Open a fresh bin when item is large and best fit leaves a wide stranded gap.
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: two-item lookahead compaction — when the residual can host both
        // the next item and a following near-mean-sized item, strongly prefer.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if next_item_size > 0 && (after_next as f64) >= 0.6 * mean_residual {
                score -= 5.0 * (1.0 - progress) * ((after_next as f64) / (mean_residual.max(1.0))).min(1.5);
            }
        }
        // NEW: penalize residuals that no plausibly-sized item (<= mean + 2σ band)
        // can ever host again — treat as dead weight, scaled by remaining stream.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let hostable_band = (mean_residual * 1.4).max(next_item_size as f64);
            if (post_residual as f64) < 0.35 * hostable_band {
                score += 7.0 * (1.0 - (post_residual as f64) / hostable_band) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bins when the existing residual would remain within
        // the hostable band (near mean residual) — an asset worth preserving.
        if next_item_size > 0 && post_residual > 0
            && (post_residual as f64) >= 0.85 * mean_residual.max(1.0)
            && (post_residual as f64) <= 1.25 * mean_residual.max(1.0) {
            new_score += 5.0 * (1.0 - progress);
        }
        // NEW: prefer fresh bins when pair waste would be near-zero AND the
        // existing residual is far below the hostable band (stranded).
        if next_fits_new && post_residual > 0 && post_residual < next_item_size {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste <= 2.0 && (post_residual as f64) < 0.4 * mean_residual.max(1.0) {
                new_score -= 8.0 * (1.0 - progress);
            }
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // Exact-fill drive — the ideal compaction outcome.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        // Residual that remains hostable by mean-sized future items is an asset.
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: dead-space recovery — reward bins whose leftover after this item
        // is small relative to the mean residual (least stranded space fleet-wide).
        if post_residual > 0 {
            let dsr = post_residual as f64 / mr;
            if dsr < 0.35 {
                score -= 2.5 * (1.0 - dsr / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // NEW: scarcity-aware waste weighting — when few bins can host the next
        // item, preserving the *only* hostable residual matters more.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 5.0 * (1.0 - progress) * (2usize.saturating_sub(fitting_bins_count)) as f64;
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Refuse fresh bins when an existing bin would leave a near-multiple
        // of the mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Refuse fresh bins when an existing bin achieves an exact fit.
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        // Refuse fresh bins when the existing residual can chain-host the
        // next item twice, leaving a still-usable remainder.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        // Open a fresh bin when the current item is large and the best
        // existing fit leaves a wide stranded gap.
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // NEW: waste-parity check — prefer the fresh bin only if its pair-waste
        // is strictly lower than the existing post-fit residual; otherwise the
        // existing bin wastes less space and should win.
        if next_fits_new && post_residual > 0 {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste >= post_residual as f64 {
                new_score += 6.0 * (1.0 - progress);
            } else {
                new_score -= 3.0 * ((post_residual as f64 - pair_waste) / 10.0).min(2.0);
            }
        }
        // NEW: late-stream consolidation — with few items remaining, avoid
        // opening bins unless the existing fit is very poor.
        if progress > 0.9 && post_frac < 0.20 {
            new_score += 8.0 * (1.0 - post_frac / 0.20) * (progress - 0.9) / 0.1;
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // Exact-fill drive — when the item exactly consumes the residual.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        // Residual that remains hostable by mean-sized future items is an asset.
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // MUTATION: two-item lookahead — reward residuals that can host next
        // item plus a following mean-sized item, reducing future dead space.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            let host2 = if after_next >= next_item_size {
                after_next - next_item_size
            } else if mean_residual > 0.0 && (after_next as f64) >= mean_residual * 0.9 {
                after_next.saturating_sub((mean_residual * 0.9) as u32)
            } else {
                after_next
            };
            let dead2 = host2 as f64 / bin_capacity as f64;
            if dead2 < 0.05 {
                score -= 10.0 * (1.0 - dead2 / 0.05) * (1.0 + 0.3 * (1.0 - progress));
            } else if dead2 > 0.15 {
                score += 5.0 * ((dead2 - 0.15) / 0.2).min(1.5) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // MUTATION: compare dead space after hosting next item in the fresh
            // pair vs the existing-bin path; prefer whichever leaves less waste.
            if post_residual > 0 {
                let existing_after = post_residual.saturating_sub(next_item_size);
                let fresh_after = pair_waste as u32;
                if fresh_after > existing_after {
                    new_score += 4.0 * ((fresh_after - existing_after) as f64 / 10.0).min(2.0)
                        * (0.4 + 0.6 * progress);
                } else if existing_after > fresh_after {
                    new_score -= 4.0 * ((existing_after - fresh_after) as f64 / 10.0).min(2.0)
                        * (0.4 + 0.6 * progress);
                }
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Refuse fresh bins when an existing residual is a near-multiple of the
        // mean residual (reusable asset).
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Refuse fresh bins when an existing bin achieves an exact fit.
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        // Refuse fresh bins when the existing residual can chain-host next twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        // Open a fresh bin when the current item is large and the best existing
        // fit leaves a wide stranded gap.
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // MUTATION: refuse fresh bins when the remaining existing residual after
        // hosting next still exceeds the mean residual (a reusable pool asset).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if (after as f64) >= mean_residual.max(1.0) {
                new_score += 6.0 * (1.0 - progress)
                    * (((after as f64) / mean_residual.max(1.0)) - 1.0).min(2.0) / 2.0;
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // Exact-fill drive: item exactly consumes the residual.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        // Residual hostable by mean-sized future items is an asset.
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Near-multiple of mean residual is a reusable asset: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Refuse fresh bins when an existing bin achieves an exact fit.
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        // Refuse fresh bins when the existing residual can chain-host the next item twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        // Open a fresh bin when the item is large and the best existing fit
        // leaves a wide stranded gap.
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead with divisibility analysis
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual near fleet mean is a good, reusable target.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // When next item cannot fit, penalize small residuals that strand space.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Near-perfect residuals: strong reward.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Awkward mid-band residuals.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Slack analysis: residual barely above next item size is excellent.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Divisibility bonus: exact multiples of next item tile perfectly.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Hostability index around mean residual.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dead-space ratio term when fleet is crowded (scaled with crowding).
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Harmonic residual sizes tile well with common item sizes.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Dead-space targeting: residuals just below mean are stranded space.
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        // Prefer squeezing into high-fill bins that can still host the next item.
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        // Exact-fill drive: item exactly consumes the residual.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        // Residual that remains hostable by mean-sized future items is an asset.
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: dead-space ratio gradient — reward bins whose post-fill ratio
        // stays high even when next item fits with slack (tighten compaction).
        if next_item_size > 0 && next_item_size <= post_residual {
            let post_fill = 1.0 - post_frac;
            if post_fill >= 0.85 {
                score -= 5.0 * (post_fill - 0.85) / 0.15 * (1.0 - progress);
            }
        }
        // NEW: penalize leaving a residual that is strictly between small
        // item sizes (dead zone), scaled by how many items it can host (0).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let dead_zone = post_residual as f64 / (next_item_size as f64);
            if dead_zone > 0.4 && dead_zone < 0.9 {
                score += 4.0 * (1.0 - ((dead_zone - 0.4) / 0.5).abs() * 2.0).max(0.0) * progress;
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Compare stranded dead space of existing fit vs fresh pair-waste.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        // Chainable existing residual: refuse fresh bins.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        // Refuse fresh bins when existing residual is near a multiple of mean.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        // Refuse fresh bins on exact fit.
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        // Refuse fresh bins when existing residual can chain-host next twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        // Open fresh bin on large item + wide stranded gap.
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bins when the existing residual, after hosting the
        // next item, would still be large enough to host the item after that
        // (triple-chain lookahead beats a fresh pair).
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            new_score += 6.0 * (1.0 - progress);
        }
        // NEW: prefer fresh bins when the existing residual would strand more
        // dead space than the fresh pair's waste, weighted by fleet crowding.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let strand = (next_item_size - post_residual) as f64;
            if strand > 0.25 * mean_residual.max(1.0) && open_bins_count <= 4 {
                new_score -= 4.0 * (strand / (0.5 * mean_residual.max(1.0))).min(2.0) * (1.0 - progress);
            }
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            // NEW: escalate penalty when many bins share this same stranded
            // pattern (post < next) — the dead space is duplicated fleet-wide.
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
        }

        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: reward residuals that can host the next item AND still leave a
        // remainder hostable by the mean-sized item — dual-chain compaction.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        // NEW: penalize consuming a scarce fit when the post-residual would be
        // tiny-but-nonzero and no other bin can host the next item.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // NEW: prefer fresh bins whose pair-waste is a clean multiple of
            // the next item size (future items can tile into it).
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size.max(1) == 0
                && pair_waste >= next_item_size as f64 {
                new_score -= 5.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bins when the existing fit leaves a post-residual
        // that is an exact multiple of the item size itself (self-tiling).
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // NEW: discourage fresh bins late when open-bin count is already low
        // and existing fits exist — consolidation beats expansion at the tail.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
            // REFINED: dead space is worse when it cannot even host the mean
            // residual-sized item — mark it as truly stranded.
            if dead_frac > 0.015 && (post_residual as f64) < 0.6 * mean_residual {
                score += 9.0 * dead_frac * bin_capacity as f64 / 20.0 * (1.0 - progress);
            }
        }

        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // Reward residuals that can host the next item AND still leave a
        // remainder hostable by the mean-sized item — dual-chain compaction.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        // Penalize consuming a scarce fit when the post-residual would be
        // tiny-but-nonzero and no other bin can host the next item.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
        // NEW: two-step lookahead — if after hosting next item the remainder
        // can still host the item after that (approximated by mean residual),
        // this bin is part of a compaction chain; reward it more strongly.
        if next_item_size > 0 && post_residual >= next_item_size
            && fitting_bins_count <= 3 {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.85 * mean_residual {
                score -= 4.0 * (1.0 - progress);
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // Prefer fresh bins whose pair-waste is a clean multiple of
            // the next item size (future items can tile into it).
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size.max(1) == 0
                && pair_waste >= next_item_size as f64 {
                new_score -= 5.0 * (1.0 - progress);
            }
            // NEW: penalize fresh bins whose pair-waste is stranded relative
            // to the fleet — dead space duplicated across many new bins.
            if pair_waste > 0.0 && (pair_waste as f64) > 1.3 * mean_residual
                && open_bins_count > 5 {
                new_score += 4.0 * ((pair_waste - 1.3 * mean_residual) / 15.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // Refuse fresh bins when the existing fit leaves a post-residual
        // that is an exact multiple of the item size itself (self-tiling).
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // Discourage fresh bins late when open-bin count is already low
        // and existing fits exist — consolidation beats expansion at the tail.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        // NEW: mid-stream consolidation guard — when many bins are open and
        // at least one existing bin fits, a new bin must justify itself by a
        // near-perfect pair (item + next item almost fill it).
        if progress > 0.35 && progress < 0.85 && fitting_bins_count >= 2
            && open_bins_count > 6 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.9 {
                new_score += 6.0 * (0.9 - pair_fill) / 0.9;
            }
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Tightness reward: strongly prefer near-full placements.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            // Exact pair: near-perfect compaction.
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item.
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                // Self-tiling: residual divisible by next item size.
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual close to fleet mean: reusable by future items.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            // Near-miss: dead space almost certainly.
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            // Dead-space ratio: stranded capacity that next item cannot use.
            let dead_frac = gap / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            // Fleet-wide duplication of the stranded pattern.
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Residual just barely above next item: tempting but wasteful.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Post-residual exactly matches item size: perfect self-compaction.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }

        // Dual-chain: after next item, remainder can host a mean-sized item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if after_next <= 2 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - after_next as f64 / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: prefer reusing existing bins as fleet grows.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            // Refuse fresh bin whose pair-waste exceeds achievable mean residual.
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            // Pair-waste tileable by next item: good fresh bin.
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
                if (pair_waste as u32) % next_item_size.max(1) == 0 {
                    new_score -= 5.0 * (1.0 - progress);
                }
            }
            // Pair-waste below mean residual: likely stranded dead space.
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            // Compare with existing-bin strand.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let existing_strand = (next_item_size - post_residual) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Refuse fresh bin when an existing bin's post-fit residual is near-perfect.
        if post_frac <= 0.10 {
            new_score += 18.0 * (1.0 - post_frac / 0.10);
        }
        // Existing bin can host the next item too: keep it open.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        // Fresh-bin waste forecast vs typical open-bin residuals.
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        // Opening attractive when fleet fragmented and item is big.
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        // Avoid opening fresh bins late when fragmentation is low.
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        // Mid-stream guard: opening a bin that leaves residual below mean is a loss.
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        // Consolidation beats expansion at the tail.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

