            // the next item lands, even though the next item fits.
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
