            }
            if fitting_bins_count <= 3 && after_next <= 6 {
                score -= 4.0 * (1.0 - after_next as f64 / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
