        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        // Near-full compaction bonus (from best-known lineage).
        if post_frac < 0.05 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            // Exact pair: near-perfect compaction.
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item.
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                if third >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                // Self-tiling: post residual divisible by next item size.
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Slack-based second-fit rewards with scarcity scaling.
            let slack = lookahead_waste;
            if slack <= 2.0 {
                let sc = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * sc * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && slack <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            // Dual-chain: after-next remainder can host a mean-sized item.
            if (lookahead_waste as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * ((lookahead_waste / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            // Near-miss: dead space almost certainly.
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
            if post_residual <= 3 && fitting_bins_count <= 2 {
                score += 10.0 * (1.0 - progress);
            }
        }

        // Dead-space guard: residual cannot host next item -> penalize proportionally.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            let dead_frac = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
        }

        // Residual just barely above next item: tempting but wasteful.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Round-number residuals are easier to fill later.
        if post_residual % 10 == 0 {
            score -= 5.0 * (1.0 - progress);
        } else if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }

        // Perfect residual matching the current item size.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: prefer reusing existing bins as fleet grows.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            // Refuse fresh bin whose pair-waste exceeds achievable mean residual.
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            // Fresh bin worse than an existing bin's post-fit residual.
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // Late-stream pair fill quality.
            if progress > 0.8 {
                let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
                if pair_fill < 0.85 {
                    new_score += 10.0 * (0.85 - pair_fill) / 0.85;
                }
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Refuse fresh bin when an existing bin's post-fit residual is near-perfect.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        // Existing bin can host the next item too: keep it open.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
            if (post_residual - next_item_size) <= 4 {
                new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
            }
        }
        // Fresh-bin waste forecast vs typical open-bin residuals.
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        // Opening attractive when fleet fragmented and item is big.
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        // Avoid opening fresh bins late when fragmentation is low.
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        // Mid-stream guard: opening a bin that leaves residual below mean is a loss.
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        // Prefer fresh bin when existing strand exceeds pair waste by a wide margin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_fits_new {
            let existing_strand = (next_item_size - post_residual) as f64;
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if existing_strand > pair_waste + 4.0 {
                new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        // Late-stream consolidation: prefer existing fits over expansion.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Global tightness pull: reward bins that end up nearly full.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item?
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Alignment with fleet mean residual is a good sign.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard with stream-length and mean-gap scaling (strengthened).
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 32.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            // Escalate when the stranded pattern is duplicated fleet-wide.
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
            // NEW: dead space that also strands the item AFTER next is doubly bad.
            if dead_frac > 0.03 && (next_item_size as f64) < 0.35 * bin_capacity as f64 {
                score += 9.0 * dead_frac * (1.0 + progress);
            }
        }

        // Near-full compaction rewards.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Mid-band awkwardness: residuals unlikely to host anything.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second-fit rewards with scarcity scaling.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Self-tiling: post residual divisible by next item size.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Mean-relative residual shaping.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Under-filled bins when many bins are open: penalize fragmentation.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Round-number residuals are easier to fill later.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // Dual-chain compaction: after-next remainder can host a mean item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        // NEW: reward exact two-item completion using mean-residual-sized items.
        if next_item_size > 0 && post_residual >= next_item_size
            && ((post_residual - next_item_size) as f64) <= mean_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / mean_residual.max(1.0));
        }
        // Penalize consuming a scarce fit leaving a tiny stranded residual.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: discourage proliferation of bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        // No existing bin can host the item: fresh bin is essential.
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // NEW: prefer a fresh bin whose pair-waste can host a mean-sized follow-up.
            if pair_waste > 0.0 && (pair_waste as f64) >= mean_residual {
                new_score -= 4.0 * (1.0 - progress)
                    * (((pair_waste as f64) / mean_residual.max(1.0)).min(2.0) - 1.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Existing bins already nearly full: fresh bin preserves them.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Fresh bin better than stranding next item in an existing bin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // Refuse fresh bins when existing fit leaves self-tiling residual.
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // Late-stream consolidation: prefer existing fits over expansion.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        // NEW: late-stream, a fresh bin whose pair-waste exceeds mean residual
        // wastes more space than consolidating into existing fits.
        if progress > 0.6 && next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste as f64 > 1.3 * mean_residual {
                new_score += 6.0 * (progress - 0.6) / 0.4
                    * (((pair_waste - mean_residual) / mean_residual.max(1.0)).min(2.0));
            }
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Global tightness pull: reward bins that end up nearly full.
        let tightness = 1.0 - post_frac;
        score -= 32.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 24.0;
            } else if lookahead_waste <= 3.0 {
                score -= 16.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item?
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Alignment with fleet mean residual is a good sign.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard with stream-length and mean-gap scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            // Escalate when the stranded pattern is duplicated fleet-wide.
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
            // NEW: dead space is worse when the residual is far below the mean
            // (nothing in the fleet will ever land there).
            if (post_residual as f64) < 0.35 * mean_residual {
                score += 6.0 * (1.0 - (post_residual as f64) / (0.35 * mean_residual.max(1.0)))
                       * (0.5 + 0.5 * progress);
            }
        }

        // Near-full compaction rewards.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Mid-band awkwardness: residuals unlikely to host anything.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second-fit rewards with scarcity scaling.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Self-tiling: post residual divisible by next item size.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Mean-relative residual shaping.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Under-filled bins when many bins are open: penalize fragmentation.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Round-number residuals are easier to fill later.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // Dual-chain compaction: after-next remainder can host a mean item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        // Penalize consuming a scarce fit leaving a tiny stranded residual.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
        // NEW: reward consuming a scarce fit when the residual exactly matches
        // a plausible future small item (residual is a common size divisor).
        if post_residual > 0 && (post_residual as f64) <= 0.5 * mean_residual
            && fitting_bins_count >= 2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: discourage proliferation of bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        // No existing bin can host the item: fresh bin is essential.
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // NEW: pair waste that can still host a mean-sized third item.
            if pair_waste as f64 >= 1.2 * mean_residual {
                new_score -= 4.0 * (1.0 - progress);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Existing bins already nearly full: fresh bin preserves them.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Fresh bin better than stranding next item in an existing bin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // Refuse fresh bins when existing fit leaves self-tiling residual.
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // Late-stream consolidation: prefer existing fits over expansion.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        // NEW: late-stream, a fresh bin is only worth it if it packs tightly.
        if progress > 0.6 && next_fits_new {
            let pair_fill2 = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill2 > 0.92 {
                new_score -= 8.0 * (pair_fill2 - 0.92) / 0.08 * (progress - 0.6) / 0.4;
            }
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Global tightness pull: reward bins that end up nearly full.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item?
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Alignment with fleet mean residual is a good sign.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard with stream-length and mean-gap scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            // Escalate when the stranded pattern is duplicated fleet-wide.
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
            // NEW: dead space that is close to but not exactly a future item size is worse
            // than dead space far from any plausible item (near-miss traps).
            if dead_frac > 0.01 {
                let near_miss = ((unusable - mean_residual) / mean_residual.max(1.0)).abs();
                if near_miss < 0.15 {
                    score += 6.0 * (1.0 - near_miss / 0.15) * (0.5 + 0.5 * progress);
                }
            }
        }

        // Near-full compaction rewards.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Mid-band awkwardness: residuals unlikely to host anything.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second-fit rewards with scarcity scaling.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Self-tiling: post residual divisible by next item size.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Mean-relative residual shaping.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Under-filled bins when many bins are open: penalize fragmentation.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Round-number residuals are easier to fill later.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // Dual-chain compaction: after-next remainder can host a mean item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        // Penalize consuming a scarce fit leaving a tiny stranded residual.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
        // NEW: triple-chain lookahead — if the residual after two more items is exactly
        // zero or tiny, this bin is a compaction gem, especially mid-stream.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let after_two = post_residual - 2 * next_item_size;
            if after_two == 0 {
                score -= 12.0 * (1.0 + 0.3 * (1.0 - progress));
            } else if after_two <= 3 {
                score -= 6.0 * (1.0 - after_two as f64 / 3.0) * (1.0 - progress);
            }
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: discourage proliferation of bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        // No existing bin can host the item: fresh bin is essential.
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // NEW: pair waste that exactly equals a near-mean residual tiles perfectly later.
            if pair_waste > 0.0 && (pair_waste as f64 / mean_residual.max(1.0)).round() >= 1.0 {
                let dev = ((pair_waste - mean_residual * (pair_waste / mean_residual.max(1.0)).round().max(1.0)) / mean_residual.max(1.0)).abs();
                if dev < 0.05 {
                    new_score -= 7.0 * (1.0 - dev / 0.05) * (1.0 - progress);
                }
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Existing bins already nearly full: fresh bin preserves them.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Fresh bin better than stranding next item in an existing bin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // Refuse fresh bins when existing fit leaves self-tiling residual.
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // Late-stream consolidation: prefer existing fits over expansion.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        // NEW: when an existing bin would absorb the item AND the next item exactly
        // (post_residual == next_item_size), opening a new bin wastes that perfect fit.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 1 {
            new_score += 16.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Dead-space guard with stream-length and mean-gap scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
        }

        // Near-full compaction rewards.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Mid-band awkwardness.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second-fit rewards with scarcity scaling.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Self-tiling: post residual divisible by next item size.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Mean-relative residual shaping.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        // Near-full compaction rewards.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item.
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let third = lookahead_waste - next_item_size as f64;
                if third < next_item_size as f64 {
                    score -= 10.0 * (1.0 - third / next_item_size.max(1) as f64);
                }
                if third >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // Residual close to fleet mean: reusable by future items.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
            // Perfect second-fit rewards with scarcity scaling.
            if lookahead_waste <= 2.0 {
                let scarcity2 = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity2 * (1.0 - lookahead_waste / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if lookahead_waste > 2.0 && lookahead_waste <= 12.0 && lookahead_waste <= mean_residual {
                score -= 3.0 * (1.0 - lookahead_waste / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && lookahead_waste <= 6.0 {
                score -= 4.0 * (1.0 - lookahead_waste / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            // Dead-space ratio: stranded capacity that next item cannot use.
            let dead_frac = gap / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }

        // Stranded residual: too small for next item and smaller than item.
        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Residual just barely above next item: tempting but wasteful.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
            score += 6.0 * (1.0 - progress);
        }

        // Post-residual far below fleet mean is good.
        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Post-residual exactly matches item size: perfect self-compaction.
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }

        // Mean-relative residual shaping.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Dual-chain: after next item, remainder can host a mean-sized item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
            if after_next <= 2 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - after_next as f64 / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
        }

        // Penalize consuming a scarce fit leaving a tiny stranded residual.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }

        // Round-number residuals are easier to fill later.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }

        // Dead-space ratio term when fleet is crowded.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
    }

    // Mean-residual consolidation term.
    let mean_weight = if progress > 0.75 { 0.35 } else { 0.5 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: prefer reusing existing bins as fleet grows.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            // Refuse fresh bin whose pair-waste exceeds achievable mean residual.
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
                if (pair_waste as u32) % next_item_size.max(1) == 0 {
                    new_score -= 6.0 * (1.0 - progress);
                }
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // Compare with existing-bin strand.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let existing_strand = (next_item_size - post_residual) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Refuse fresh bin when an existing bin's post-fit residual is near-perfect.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        // Existing bin can host the next item too: keep it open.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        // Fresh-bin waste forecast vs typical open-bin residuals.
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        // Opening attractive when fleet fragmented and item is big.
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        // Avoid opening fresh bins late when fragmentation is low.
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        // Mid-stream guard: opening a bin that leaves residual below mean is a loss.
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // Refuse fresh bins when existing fit leaves self-tiling residual.
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // Consolidation beats expansion at the tail.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        score += new_score;
    }

    // Mild consolidation pressure with many open bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0 + 60.0 * progress;
    } else {
        // Global tightness: reward bins that end up nearly full.
        let tightness = 1.0 - post_frac;
        score -= 30.0 * tightness * tightness;

        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            let next_tightness = 1.0 - lookahead_waste / post_residual as f64;
            let next_scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= next_scarcity * (55.0 + 0.4 * next_item_size as f64 - 0.3 * lookahead_waste
                     + 22.0 * next_tightness * next_tightness) * (1.0 + 0.3 * (1.0 - progress));
            if lookahead_waste == 0.0 {
                score -= 22.0;
            } else if lookahead_waste <= 3.0 {
                score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
            }
            // Chain lookahead: leftover after next item can host a third item?
            if (lookahead_waste as u32) >= next_item_size {
                score -= 8.0 * (1.0 - progress);
                let after = lookahead_waste - next_item_size as f64;
                if after < next_item_size as f64 {
                    score -= 10.0 * (1.0 - after / next_item_size.max(1) as f64);
                }
                if after >= 2.0 * next_item_size as f64 {
                    score -= 5.0 * (1.0 - progress);
                }
                let rem = (post_residual as u32) % next_item_size.max(1);
                if rem == 0 {
                    score -= 7.0 * (1.0 - progress);
                } else if rem <= 2 {
                    score -= 3.0 * (1.0 - rem as f64 / 3.0) * (1.0 - progress);
                }
            }
            // NEW: dead-space after next item scaled by fleet mean residual.
            if lookahead_waste > 0.0 && (lookahead_waste as f64) < 0.5 * mean_residual {
                score += 6.0 * (1.0 - lookahead_waste / (0.5 * mean_residual).max(1.0))
                         * (1.0 - progress);
            }
            // Alignment with fleet mean residual is a good sign.
            let res_gap = ((post_residual as f64) - mean_residual).abs();
            if res_gap < 4.0 {
                score -= 4.0 * (1.0 - res_gap / 4.0) * (1.0 - progress);
            }
            if (post_residual as f64) >= 0.9 * mean_residual
                && (post_residual as f64) <= 1.3 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (1.0 - res_gap / (0.4 * mean_residual).max(1.0)).max(0.0);
            }
        } else if next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
            if post_frac < 0.25 {
                let awkward = 1.0 - (post_frac.max(0.05)) / 0.25;
                score += 4.0 * awkward;
            }
            if gap <= 5.0 {
                score += 3.0 * (1.0 - gap / 5.0);
            }
            if gap > 10.0 && gap <= 25.0 && (next_item_size as f64) < 1.5 * mean_residual {
                score += 1.5 * (1.0 - (gap - 10.0) / 15.0) * (1.0 - progress);
            }
            if gap > 25.0 && (post_residual as f64) > 0.6 * mean_residual {
                score += 2.0 * ((gap - 25.0) / 20.0).min(1.5) * (1.0 - progress);
            }
            // NEW: when many bins could host the next item, wasting this residual is cheap.
            if fitting_bins_count >= 3 {
                score -= 1.5 * ((fitting_bins_count - 3) as f64).min(4.0) * (1.0 - progress);
            }
        }

        if post_residual < 10 {
            let small_hope = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
            score += 22.0 * (1.0 - progress) * (0.6 + 0.4 * small_hope);
        } else if post_residual < 20 {
            score += 10.0 - 6.0 * progress;
        }

        if next_item_size > post_residual && post_residual < item_size {
            score += 12.0 * (1.0 - progress);
            if post_residual < 5 {
                score += 8.0 * (1.0 - progress);
            }
        }

        // Dead-space guard with stream-length and mean-gap scaling.
        if next_item_size > 0 && post_residual < next_item_size {
            let mean_gap = (mean_residual - post_residual as f64).max(0.0);
            score += 0.15 * mean_gap.min(30.0);
            if (post_residual as f64) < 0.5 * next_item_size as f64 {
                score += 8.0 * (1.0 - progress);
            }
            score += 10.0 * (1.0 - progress) * (1.0 - post_frac);
            let unusable = (next_item_size - post_residual) as f64;
            let dead_frac = unusable / bin_capacity as f64;
            if dead_frac > 0.02 {
                score += 25.0 * dead_frac * (0.4 + 0.6 * (1.0 - progress));
            }
            // Escalate when the stranded pattern is duplicated fleet-wide.
            if fitting_bins_count == 0 && dead_frac > 0.01 {
                score += 14.0 * dead_frac * bin_capacity as f64 / 10.0 * (0.5 + 0.5 * progress);
            }
            // NEW: dead space is worse when the next item itself is large.
            if next_item_size as f64 > 0.3 * bin_capacity as f64 {
                score += 6.0 * (1.0 - progress) * (next_item_size as f64 / bin_capacity as f64);
            }
        }

        // Near-full compaction rewards.
        if post_frac < 0.05 && post_residual > 0 {
            score -= 22.0 * (1.0 - post_frac / 0.05);
        } else if post_frac < 0.10 {
            score -= 6.0 * (1.0 - (post_frac - 0.05) / 0.05);
        }

        // Mid-band awkwardness: residuals unlikely to host anything.
        if post_frac >= 0.10 && post_frac < 0.25 {
            let awkward = 1.0 - (post_frac - 0.10) / 0.15;
            let unhostable = next_item_size > 0 && next_item_size > post_residual;
            score += 4.0 * awkward * if unhostable { 1.0 } else { 0.3 };
        }

        // Perfect second-fit rewards with scarcity scaling.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 2.0 {
                let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
                score -= 14.0 * scarcity * (1.0 - slack / 2.0) * (1.0 + 0.4 * (1.0 - progress));
            }
            if slack == 0.0 && fitting_bins_count <= 4 {
                score -= 9.0 * (1.0 + 0.3 * (1.0 - progress));
            }
            if slack > 2.0 && slack <= 12.0 && (slack as f64) <= mean_residual {
                score -= 3.0 * (1.0 - slack / 12.0) * (1.0 - progress);
            }
            if fitting_bins_count <= 3 && slack <= 6.0 {
                score -= 4.0 * (1.0 - slack / 6.0) * (1.0 - progress)
                    * (1.0 + (3usize.saturating_sub(fitting_bins_count)) as f64 * 0.25);
            }
            // NEW: reward fits that leave a residual still matching the fleet mean.
            if slack > 0.0 && ((slack - mean_residual).abs()) < 3.0 {
                score -= 4.0 * (1.0 - (slack - mean_residual).abs() / 3.0) * (1.0 - progress);
            }
        }

        if (post_residual as f64) < 0.5 * mean_residual && post_residual > 0 {
            score -= 3.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        }

        // Self-tiling: post residual divisible by next item size.
        if next_item_size > 0 && post_residual > next_item_size {
            let q = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && q >= 2 {
                score -= 5.0 * (1.0 - progress) * (q as f64).min(4.0) / 4.0;
            }
        }

        // Mean-relative residual shaping.
        let mr = mean_residual.max(1.0);
        if post_residual > 0 {
            let rel = post_residual as f64 / mr;
            if rel >= 1.0 && rel <= 1.6 {
                score -= 4.0 * (1.0 - progress) * (1.6 - rel) / 0.6;
            } else if rel > 0.55 && rel < 1.0 {
                score += 5.0 * (1.0 - progress) * (1.0 - (1.0 - rel) / 0.45).max(0.0);
            } else if rel > 1.6 {
                let near_mult = ((rel - (rel / 2.0).round() * 2.0).abs() * mr) < 3.0;
                if near_mult {
                    score -= 3.0 * (1.0 - progress);
                } else {
                    score += 1.5 * (1.0 - progress) * ((rel - 1.6) / 2.0).min(1.5);
                }
            }
        }

        // Under-filled bins when many bins are open: penalize fragmentation.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 && open_bins_count > 3 {
            let crowd = ((open_bins_count - 3) as f64 / 8.0).min(1.0);
            score += 10.0 * (0.5 - fill_ratio) * (1.0 + crowd);
        }
        if fill_ratio < 0.65 && open_bins_count > 5
            && next_item_size > 0 && next_item_size > post_residual {
            score += 6.0 * (0.65 - fill_ratio) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fill_ratio < 0.8 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.08 * stranded * (0.5 + 0.5 * progress);
        }
        // Round-number residuals are easier to fill later.
        if post_residual > 0 {
            let pr = post_residual;
            if pr % 10 == 0 {
                score -= 5.0 * (1.0 - progress);
            } else if pr % 5 == 0 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual <= 2 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual > 0 {
            let below = mean_residual - post_residual as f64;
            if below > 0.0 && below < 0.5 * mean_residual {
                score += 3.0 * (1.0 - below / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
        }
        if fill_ratio >= 0.75 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0 * (fill_ratio - 0.75) / 0.25 * (1.0 - post_frac / (1.0 - fill_ratio + 0.01)).min(1.0);
        }
        if post_residual == item_size {
            score -= 18.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && (post_residual as f64) >= 0.8 * mean_residual
            && (post_residual as f64) <= 1.2 * mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
        // Dual-chain compaction: after-next remainder can host a mean item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if (after_next as f64) >= 0.5 * mean_residual {
                score -= 5.0 * (1.0 - progress)
                    * (((after_next as f64) / mean_residual.max(1.0)).min(2.0) / 2.0);
            }
        }
        // Penalize consuming a scarce fit leaving a tiny stranded residual.
        if post_residual > 0 && post_residual <= 3 && fitting_bins_count <= 2
            && next_item_size > post_residual {
            score += 10.0 * (1.0 - progress);
        }
    }

    let mean_weight = if progress > 0.75 { 0.35 } else { 0.55 };
    score += mean_weight * (mean_residual - post_residual as f64);

    // Open-bin pressure: discourage proliferation of bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 8.0 * progress);

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let next_fits_new = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let scarcity = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        let mut new_score = 30.0 - 15.0 * scarcity - (open_bins_count as f64).min(10.0)
                            - 6.0 * (fitting_bins_count as f64).min(4.0);
        // No existing bin can host the item: fresh bin is essential.
        if fitting_bins_count == 0 {
            new_score -= 100.0;
        }
        if next_fits_new && scarcity > 0.0 {
            new_score -= 18.0 * (1.0 - progress);
        }
        if next_fits_new {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            if pair_waste < 10.0 {
                new_score -= 12.0 * (1.0 - pair_waste / 10.0);
                if pair_waste == 0.0 {
                    new_score -= 25.0;
                }
            } else if pair_waste > 30.0 {
                new_score += 0.15 * (pair_waste - 30.0).min(40.0);
            }
            if fitting_bins_count <= 3 && pair_waste <= 4.0 {
                new_score -= 20.0 * (1.0 - pair_waste / 4.0) * (1.0 + 0.5 * (1.0 - progress));
            }
            if pair_waste as f64 > mean_residual * 1.2 {
                new_score += 5.0 * ((pair_waste - mean_residual) / 10.0).min(2.0);
            }
            if item_size + next_item_size < bin_capacity / 2 {
                new_score += 8.0 * (1.0 - progress);
            }
            if pair_waste >= next_item_size as f64 {
                new_score -= 10.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as u32) % next_item_size == 0 {
                new_score -= 6.0 * (1.0 - progress);
            }
            if pair_waste > 0.0 && (pair_waste as f64) - mean_residual > 20.0 {
                new_score += 3.0 * (((pair_waste as f64) - mean_residual - 20.0) / 15.0).min(2.0);
            }
            if pair_waste > 0.0 && (pair_waste as f64) < 0.85 * mean_residual {
                new_score += 4.0 * (1.0 - progress) * (1.0 - pair_waste / (0.85 * mean_residual));
            }
            if pair_waste > 0.0 && pair_waste as u32 % 10 == 0 {
                new_score -= 4.0 * (1.0 - progress);
            } else if pair_waste > 0.0 && pair_waste as u32 % 5 == 0 {
                new_score -= 2.0 * (1.0 - progress);
            }
            if pair_waste > post_residual as f64 {
                new_score += 5.0 * ((pair_waste - post_residual as f64) / 8.0).min(2.0);
            }
            // NEW: fresh bin wasted if pair_waste is much larger than the fleet mean residual.
            if pair_waste > 0.0 && (pair_waste as f64) > 1.8 * mean_residual {
                new_score += 4.0 * (((pair_waste as f64) / mean_residual.max(1.0)) - 1.8).min(2.0);
            }
        } else if progress > 0.8 {
            new_score += 15.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 12.0;
        }
        if progress > 0.85 {
            new_score += 10.0;
        }
        // Existing bins already nearly full: fresh bin preserves them.
        if post_frac <= 0.10 {
            new_score += 20.0 * (1.0 - post_frac / 0.10);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score += 14.0;
        }
        if (post_residual as f64) < mean_residual {
            new_score += 3.0 * (mean_residual - post_residual as f64).min(20.0) / 4.0;
        }
        if item_size as f64 > 0.4 * bin_capacity as f64 && mean_residual > 1.5 * item_size as f64 {
            new_score -= 6.0;
        }
        if progress > 0.9 && mean_residual < 0.15 * bin_capacity as f64 {
            new_score += 6.0 * (progress - 0.9) / 0.1;
        }
        if post_residual > 0 && (post_residual as f64) < 0.6 * mean_residual && progress < 0.9 {
            new_score += 4.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
        if open_bins_count > 6 && next_fits_new {
            new_score += 0.8 * ((open_bins_count - 6) as f64).min(8.0);
        }
        if progress < 0.3 && fitting_bins_count <= 2 && open_bins_count > 3 {
            new_score -= 6.0;
        }
        if progress > 0.8 && next_fits_new {
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill < 0.85 {
                new_score += 10.0 * (0.85 - pair_fill) / 0.85;
            }
        }
        if fitting_bins_count <= 1 && item_size as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
            new_score -= 8.0 * (1.0 - progress);
        }
        // Fresh bin better than stranding next item in an existing bin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let existing_strand = (next_item_size - post_residual) as f64;
            if next_fits_new {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
                if existing_strand > pair_waste + 4.0 {
                    new_score -= 3.0 * ((existing_strand - pair_waste) / 10.0).min(2.5);
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            new_score += 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 4 {
            new_score += 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let mr2 = mean_residual.max(1.0);
            let rel = post_residual as f64 / mr2;
            let near_mean_mult = ((rel - rel.round()).abs() * mr2) <= 2.0;
            if near_mean_mult && rel.round() >= 1.0 {
                new_score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == item_size {
            new_score += 25.0 * (1.0 + 0.3 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            new_score += 8.0 * (1.0 - progress);
        }
        if next_fits_new && item_size as f64 > 0.5 * bin_capacity as f64
            && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > 0.15 * bin_capacity as f64 {
            new_score -= 10.0 * (1.0 - progress);
        }
        // Refuse fresh bins when existing fit leaves self-tiling residual.
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
            new_score += 6.0 * (1.0 - progress);
        }
        // Late-stream consolidation: prefer existing fits over expansion.
        if progress > 0.7 && fitting_bins_count >= 1 && open_bins_count <= 4 {
            new_score += 5.0 * (progress - 0.7) / 0.3;
        }
        // NEW: when several existing bins fit the item, expansion is rarely justified.
        if fitting_bins_count >= 2 && post_residual > 0 {
            new_score += 3.0 * ((fitting_bins_count - 2) as f64).min(4.0) * (0.5 + 0.5 * progress);
        }
        score += new_score;
    }

    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}
